/** An operator starts a finite approved queue; only its next SMS is dispatched. */
final class SmsScreen {
 private final Activity a;private final Vault vault;private final ExecutorService io=Executors.newSingleThreadExecutor();
 private final Handler handler=new Handler(Looper.getMainLooper());private final SmsRun run=new SmsRun();
 private JSONObject config=new JSONObject(),job;private TextView status,preview,connection,counts,timer;private EditText code,id,key;private Spinner sims,interval;
 private LinearLayout settings;private Button connect,start,pause,review,send,report;private boolean busy,awaiting,destroyed,active=true,storageFailed,stopping;
 private BroadcastReceiver receiver;private int selectedSim=-1;private final ArrayList<Integer> subscriptionIds=new ArrayList<>();
 private final int green=Color.rgb(20,92,70),muted=Color.rgb(98,117,108);private Runnable timeout;
 SmsScreen(Activity activity){a=activity;vault=new Vault(a);}
 private int dp(int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
 private GradientDrawable box(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView text(LinearLayout root,String value,int size,boolean bold){TextView t=new TextView(a);t.setText(value);t.setTextSize(size);t.setTextColor(bold?green:muted);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(5),0,dp(5));root.addView(t);return t;}
 private LinearLayout card(LinearLayout root){LinearLayout c=new LinearLayout(a);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(12),dp(18),dp(16));c.setBackground(box(Color.WHITE,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(14));root.addView(c,p);return c;}
 private EditText field(LinearLayout root,String label,boolean secret){text(root,label,13,true);EditText v=new EditText(a);v.setSingleLine(true);v.setTextSize(15);v.setPadding(dp(10),dp(10),dp(10),dp(10));v.setBackground(box(Color.rgb(236,244,239),8));if(secret)v.setInputType(129);root.addView(v,new LinearLayout.LayoutParams(-1,-2));return v;}
 private Button button(LinearLayout root,String label,Runnable action){Button b=new Button(a);b.setText(label);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(new android.content.res.ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{Color.rgb(154,172,161),green}));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(8),0,0);root.addView(b,p);return b;}
 void show(){
  ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(241,246,242));LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(16),dp(18),dp(22));scroll.addView(root);a.setContentView(scroll);
  LinearLayout header=card(root);ImageView logo=new ImageView(a);int icon=a.getResources().getIdentifier("school_launcher","mipmap",a.getPackageName());logo.setImageResource(icon==0?R.drawable.schoolflow_icon:icon);logo.setContentDescription("School logo");logo.setScaleType(ImageView.ScaleType.FIT_CENTER);header.addView(logo,new LinearLayout.LayoutParams(dp(60),dp(60)));text(header,a.getString(R.string.app_name),23,true);text(header,"School SIM messaging",14,false);connection=text(header,"Connect your registered school phone once.",14,true);
  LinearLayout progress=card(root);counts=text(progress,"Queue not checked",17,true);timer=text(progress,"Default interval · 20 seconds",14,false);status=text(progress,"Open the app, select the school SIM, then tap Send Messages.",14,false);
  LinearLayout controls=card(root);text(controls,"Sending SIM",13,true);sims=new Spinner(a);controls.addView(sims,new LinearLayout.LayoutParams(-1,dp(48)));
  button(controls,"Enable permission / Refresh SIMs",this::permission);text(controls,"Time between messages",13,true);interval=new Spinner(a);interval.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"15 seconds","20 seconds (recommended)","25 seconds"}));interval.setSelection(1);controls.addView(interval,new LinearLayout.LayoutParams(-1,dp(48)));
  start=button(controls,"Send Messages",this::prepareRun);pause=button(controls,"Pause sending",()->stopRun("Paused. An SMS already submitted cannot be recalled.",true));
  text(controls,"A message may use several SMS parts. Your selected SIM package/network charges apply. Keep this app open; leaving it pauses the queue.",12,false);
  LinearLayout next=card(root);text(next,"Current message",14,true);preview=text(next,"No message selected.",16,false);review=button(next,"Review next SMS manually",this::claimManual);send=button(next,"Send reviewed SMS",this::confirmManual);report=button(next,"Upload saved result (does not resend)",this::reportResult);button(next,"Resolve uncertain local message",this::resolve);
  LinearLayout setup=card(root);button(setup,"School connection settings",()->settings.setVisibility(settings.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));settings=new LinearLayout(a);settings.setOrientation(LinearLayout.VERTICAL);setup.addView(settings);code=field(settings,"Institute Code",false);id=field(settings,"Phone ID",false);id.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);key=field(settings,"Connection Key",true);connect=button(settings,"Connect school phone",this::connect);
  try{config=new JSONObject(vault.read());job=config.optJSONObject("job");code.setText(BuildConfig.INSTITUTE_CODE.isEmpty()?config.optString("code"):BuildConfig.INSTITUTE_CODE);code.setEnabled(BuildConfig.INSTITUTE_CODE.isEmpty());id.setText(config.optString("device"));key.setText(config.optString("key"));int seconds=config.optInt("interval",20);interval.setSelection(seconds==15?0:seconds==25?2:1);settings.setVisibility(config.has("scope")?View.GONE:View.VISIBLE);showJob();if(job!=null)status.setText("Saved message recovered. Started or uncertain messages are never sent again automatically.");}
  catch(Exception e){storageFailed=true;status.setText("Private storage unavailable. Contact the school before reconnecting; pending messages must be reviewed.");}
  loadSims();controls();if(config.has("scope")&&!storageFailed)refresh();
 }
 private void controls(){if(start==null||destroyed)return;boolean free=!busy&&!storageFailed;
  connect.setEnabled(free&&!run.running()&&job==null);code.setEnabled(free&&!run.running()&&job==null&&BuildConfig.INSTITUTE_CODE.isEmpty());id.setEnabled(free&&!run.running()&&job==null);key.setEnabled(free&&!run.running()&&job==null);
  start.setEnabled(free&&active&&!awaiting&&!run.running()&&job==null&&config.has("scope"));pause.setEnabled(config.has("batch")&&!storageFailed);sims.setEnabled(free&&!run.running()&&!awaiting);interval.setEnabled(free&&!run.running()&&!awaiting);
  review.setEnabled(free&&!run.running()&&job==null&&config.has("scope"));send.setEnabled(free&&active&&!run.running()&&job!=null&&"claimed".equals(config.optString("stage")));report.setEnabled(free&&!awaiting&&job!=null&&config.has("outcome"));
 }
 private interface Work {JSONObject perform() throws Exception;}private interface Done {void accept(JSONObject result) throws Exception;}
 private void task(Work work,Done done){if(busy||destroyed||storageFailed)return;busy=true;controls();io.execute(()->{JSONObject result=null;Exception error=null;try{result=work.perform();}catch(Exception e){error=e;}final JSONObject value=result;final Exception failure=error;a.runOnUiThread(()->{if(destroyed)return;busy=false;try{if(failure!=null)throw failure;done.accept(value);}catch(Exception e){run.stop();a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);status.setText("Connection failed or action refused. Sending paused. Saved/uncertain messages are not resent; review the school outbox.");}controls();if(stopping&&!busy)stopRemote();});});}
 private static final class ApiException extends IOException { final int statusCode; ApiException(int code){super("Action refused");statusCode=code;} }
 private JSONObject call(String action,JSONObject body)throws Exception{
  if(!SchoolBinding.matches(BuildConfig.INSTITUTE_CODE,BuildConfig.SCHOOL_SCOPE,config.optString("code"),config.optString("school_scope",BuildConfig.SCHOOL_SCOPE)))throw new IOException("Wrong school");String did=config.getString("device");if(!did.matches("[1-9][0-9]{0,8}"))throw new IOException();HttpURLConnection c=(HttpURLConnection)new URL(EndpointPolicy.BASE+"/api/sms/devices/"+did+"/"+action).openConnection();
  try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(20000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("X-Institute-Code",config.getString("code"));c.setRequestProperty("Authorization","Bearer "+config.getString("key"));if(config.has("scope"))c.setRequestProperty("X-Device-Scope",config.getString("scope"));try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}int statusCode=c.getResponseCode();if(statusCode!=200)throw new ApiException(statusCode);try(InputStream in=c.getInputStream()){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buffer=new byte[2048];int n;while((n=in.read(buffer))!=-1){if(b.size()+n>16384)throw new IOException();b.write(buffer,0,n);}return new JSONObject(b.toString("UTF-8"));}}finally{c.disconnect();}
 }
 private void save()throws Exception{vault.save(config.toString());}
 private void acceptHeartbeat(JSONObject h)throws Exception{if(!SchoolBinding.matches(BuildConfig.INSTITUTE_CODE,BuildConfig.SCHOOL_SCOPE,config.getString("code"),h.optString("school_scope")))throw new IOException("Wrong school");if(config.has("scope")&&!h.getString("scope").equals(config.getString("scope")))throw new IOException("Connection rotated");config.put("scope",h.getString("scope")).put("school_scope",h.getString("school_scope"));if(!config.has("batch")&&h.optJSONObject("active_batch")!=null)config.put("batch",h.getJSONObject("active_batch").getString("id"));save();connection.setText("Connected · "+h.optString("school_name")+"\n"+h.getString("name")+" · "+h.getString("campus"));counts.setText(h.optInt("queued")+" queued for this phone");}
 private void connect(){if(busy||job!=null)return;String school=code.getText().toString().trim().toUpperCase(Locale.ROOT),device=id.getText().toString().trim(),secret=key.getText().toString().trim();if(!school.matches("[A-Z0-9][A-Z0-9-]{2,39}")||!device.matches("[1-9][0-9]{0,8}")||!secret.matches("[A-Za-z0-9_-]{43}")){status.setText("Check the institute code, numeric phone ID and connection key.");return;}
  final JSONObject previous=config;try{config=new JSONObject().put("code",school).put("device",device).put("key",secret);}catch(JSONException e){return;}task(()->{try{return call("heartbeat",new JSONObject());}catch(Exception e){config=previous;throw e;}},h->{acceptHeartbeat(h);settings.setVisibility(View.GONE);status.setText("Connection saved. Choose the school SIM and tap Send Messages.");});
 }
 private void refresh(){task(()->call("heartbeat",new JSONObject()),this::acceptHeartbeat);}
 private boolean permitted(){return a.checkSelfPermission(Manifest.permission.SEND_SMS)==PackageManager.PERMISSION_GRANTED&&a.checkSelfPermission(Manifest.permission.READ_PHONE_STATE)==PackageManager.PERMISSION_GRANTED;}
 private void permission(){if(!permitted())a.requestPermissions(new String[]{Manifest.permission.SEND_SMS,Manifest.permission.READ_PHONE_STATE},13);else loadSims();}
 void permissions(int request){if(request==13){loadSims();controls();}}
 @SuppressWarnings("MissingPermission") private void loadSims(){if(sims==null)return;subscriptionIds.clear();ArrayList<String> labels=new ArrayList<>();if(permitted())try{SubscriptionManager manager=(SubscriptionManager)a.getSystemService(Context.TELEPHONY_SUBSCRIPTION_SERVICE);List<SubscriptionInfo> available=manager.getActiveSubscriptionInfoList();if(available!=null)for(SubscriptionInfo info:available){subscriptionIds.add(info.getSubscriptionId());labels.add("SIM "+(info.getSimSlotIndex()+1)+" · "+info.getCarrierName());}}catch(Exception e){status.setText("SIM information unavailable. Check phone permissions.");}sims.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));int remembered=config.optInt("sim",-1);if(subscriptionIds.contains(remembered))sims.setSelection(subscriptionIds.indexOf(remembered));if(labels.isEmpty())status.setText("Allow SMS/phone permission and insert an active school SIM.");}
 private boolean selectSim(){if(!permitted()){permission();status.setText("Allow permission, select the school SIM, then tap Send Messages again.");return false;}int pos=sims.getSelectedItemPosition();if(pos<0||pos>=subscriptionIds.size()){status.setText("No active school SIM selected.");return false;}selectedSim=subscriptionIds.get(pos);try{config.put("sim",selectedSim);save();return true;}catch(Exception e){storageFailed=true;controls();return false;}}
 private String newToken(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
 private JSONObject batchReference()throws JSONException{return new JSONObject().put("batch",config.getString("batch"));}
 private void prepareRun(){if(!active||busy||job!=null||!selectSim())return;final int seconds=interval.getSelectedItemPosition()==0?15:interval.getSelectedItemPosition()==2?25:20;
  try{config.put("interval",seconds);if(!config.has("batch"))config.put("batch",newToken());save();}catch(Exception e){storageFailed=true;controls();return;}
  // Retire a recovered run explicitly, then obtain a finite queue snapshot.
  final String old=config.optString("batch");final String fresh=newToken();task(()->{try{call("batch-stop",new JSONObject().put("batch",old));}catch(ApiException e){if(e.statusCode!=404)throw e;}return call("heartbeat",new JSONObject());},h->{acceptHeartbeat(h);config.put("batch",fresh);save();task(()->call("batch",new JSONObject().put("id",fresh).put("interval",seconds)),response->{JSONObject batch=response.optJSONObject("batch");if(batch==null){config.remove("batch");save();status.setText("No queued SMS. Release approved parent messages from the school software first.");return;}showCounts(batch);if(!active){stopRun("App paused. Tap Send Messages when ready.",true);return;}new AlertDialog.Builder(a).setTitle("Start sending messages?").setMessage(batch.getInt("total")+" queued message(s), one every "+seconds+" seconds, using the selected school SIM. Multipart messages can use several SMS credits. SIM/network charges apply. Keep this app open.").setNegativeButton("Cancel",(d,w)->stopRun("Sending cancelled. Nothing dispatched.",true)).setOnCancelListener(d->stopRun("Sending cancelled. Nothing dispatched.",true)).setPositiveButton("Send Messages",(d,w)->{if(!active)return;run.start(seconds);a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);status.setText("Sending run started. You can pause at any time.");controls();tick();}).show();});});
 }
 private void showCounts(JSONObject b){counts.setText("This run · "+b.optInt("sent")+" submitted · "+b.optInt("pending")+" pending\n"+b.optInt("failed")+" failed · "+b.optInt("unknown")+" uncertain");}
 private void showJob(){if(preview!=null)preview.setText(job==null?"No message selected.":job.optString("phone")+"\n\n"+job.optString("text"));}
 private final Runnable nextTick=this::tick;
 private void tick(){handler.removeCallbacks(nextTick);if(!active||!run.running()||destroyed)return;if(busy||awaiting){handler.postDelayed(nextTick,1000);return;}long wait=run.delay(SystemClock.elapsedRealtime());if(wait>0){timer.setText("Next message in "+((wait+999)/1000)+" seconds");handler.postDelayed(nextTick,1000);return;}timer.setText("Checking approved queue…");claim(true);}
 private void claimManual(){if(!active||busy||job!=null)return;if(config.has("batch")){stopRun("Previous run paused. Tap Review next SMS again.",true);return;}claim(false);}
 private void claim(boolean automatic){task(()->call("claim",automatic?batchReference():new JSONObject()),response->{JSONObject b=response.optJSONObject("batch");if(b!=null)showCounts(b);if(response.optBoolean("paused")||response.optBoolean("complete")){run.stop();a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);status.setText(response.optBoolean("complete")?"Run complete. Tap Send Messages again for newly queued SMS.":"Run paused. Review failed or uncertain messages in the school outbox.");config.remove("batch");save();timer.setText("Sending stopped");return;}int wait=response.optInt("wait_seconds");if(wait>0){run.serverWait(SystemClock.elapsedRealtime(),wait);tick();return;}job=response.optJSONObject("job");if(job==null){if(automatic)stopRun("No pending SMS in this run.",true);else status.setText("No queued SMS for this phone.");return;}config.put("job",job).put("stage","claimed");config.remove("outcome");save();showJob();if(automatic){if(active&&run.running())dispatch();else stopRun("Paused before dispatch.",true);}else status.setText("Review recipient and message, then send using the selected SIM.");});}
 private void confirmManual(){if(job==null||!"claimed".equals(config.optString("stage"))||!selectSim())return;new AlertDialog.Builder(a).setTitle("Send reviewed SMS?").setMessage(job.optString("phone")+"\nYour selected SIM package/network charges apply.").setNegativeButton("Cancel",null).setPositiveButton("Send once",(d,w)->dispatch()).show();}
 private JSONObject reference()throws JSONException{JSONObject r=new JSONObject().put("id",job.getString("id")).put("token",job.getString("token"));if(run.running()&&config.has("batch"))r.put("batch",config.getString("batch"));return r;}
 @SuppressWarnings("MissingPermission") private boolean simPresent(){if(!permitted()||selectedSim<0)return false;try{return ((SubscriptionManager)a.getSystemService(Context.TELEPHONY_SUBSCRIPTION_SERVICE)).getActiveSubscriptionInfo(selectedSim)!=null;}catch(Exception e){return false;}}
 private void dispatch(){if(!active||job==null||!"claimed".equals(config.optString("stage"))||!simPresent()){stopRun("Sending paused. Check the selected SIM and permissions.",true);return;}try{final JSONObject ref=reference();config.put("stage","started").put("outcome","unknown");save();task(()->call("start",ref),response->{if(!active||!run.running()&&config.has("batch")){status.setText("Paused after dispatch authorization. Do not resend; review this uncertain message.");reportResult();return;}sendParts();});}catch(Exception e){stopRun("Could not save dispatch state. Nothing further will be sent.",false);}}
 @SuppressWarnings("MissingPermission") private void sendParts(){if(!active||destroyed||!simPresent()){finishResult("unknown");return;}awaiting=true;controls();run.dispatched(SystemClock.elapsedRealtime());String action=a.getPackageName()+".SENT."+UUID.randomUUID();final Set<Integer> seen=new HashSet<>();final boolean[] failed={false};
  try{SmsManager manager=SmsManager.getSmsManagerForSubscriptionId(selectedSim);ArrayList<String> parts=manager.divideMessage(job.getString("text"));if(parts.isEmpty())throw new IOException();final int expected=parts.size();receiver=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){int part=intent.getIntExtra("part",-1);if(part<0||part>=expected||!seen.add(part))return;if(getResultCode()!=Activity.RESULT_OK)failed[0]=true;if(seen.size()==expected){unregister();finishResult(failed[0]?"unknown":"sent");}}};if(Build.VERSION.SDK_INT>=33)a.registerReceiver(receiver,new IntentFilter(action),Context.RECEIVER_NOT_EXPORTED);else a.registerReceiver(receiver,new IntentFilter(action));ArrayList<PendingIntent> callbacks=new ArrayList<>();for(int i=0;i<expected;i++)callbacks.add(PendingIntent.getBroadcast(a,i,new Intent(action).setPackage(a.getPackageName()).putExtra("part",i),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));timeout=()->{if(awaiting){unregister();finishResult("unknown");}};handler.postDelayed(timeout,90000);manager.sendMultipartTextMessage(job.getString("phone"),null,parts,callbacks,null);status.setText("Submitting SMS to the phone network…");}
  catch(Exception e){unregister();finishResult("unknown");}
 }
 private void finishResult(String outcome){if(timeout!=null)handler.removeCallbacks(timeout);awaiting=false;if(!"sent".equals(outcome))run.uncertain();try{config.put("outcome",outcome);save();status.setText("Phone result: "+outcome+". Uploading to the school outbox; recipient delivery is not verified.");controls();reportResult();}catch(Exception e){storageFailed=true;stopRun("Result could not be saved. Review phone SMS history; do not resend.",false);}}
 private void reportResult(){if(job==null||awaiting||!config.has("outcome"))return;final String outcome=config.optString("outcome");task(()->call("result",reference().put("state",outcome).put("detail","Android SIM submission; recipient delivery not verified")),response->{config.remove("job");config.remove("stage");config.remove("outcome");job=null;save();showJob();if(!"sent".equals(outcome)){stopRun("Uncertain SMS recorded. Run paused; inspect phone SMS history before continuing.",true);}else if(active&&run.running()){status.setText("SMS submitted. Waiting for the next scheduled message.");tick();}else{status.setText("Phone result saved. This SMS will not be resent.");if(config.has("batch"))stopRun("Run paused. Phone result saved.",true);}});}
 private void stopRun(String message,boolean remote){run.stop();handler.removeCallbacks(nextTick);a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(status!=null)status.setText(message);if(timer!=null)timer.setText("Sending paused");if(remote&&config.has("batch")){stopping=true;if(!busy)stopRemote();}controls();}
 private void stopRemote(){if(!stopping||busy||!config.has("batch"))return;stopping=false;task(()->call("batch-stop",batchReference()),response->{if(job!=null&&"claimed".equals(config.optString("stage"))){job=null;config.remove("job");config.remove("stage");config.remove("outcome");showJob();}config.remove("batch");save();JSONObject b=response.optJSONObject("batch");if(b!=null)showCounts(b);});}
 private void resolve(){if(job==null||awaiting||busy||run.running())return;new AlertDialog.Builder(a).setTitle("Review uncertain message first").setMessage("Inspect this recipient/message in the phone SMS history and the school outbox. Clearing the local record never resends it. A server-started message is never requeued automatically.").setNegativeButton("Cancel",null).setPositiveButton("Clear reviewed local record",(d,w)->{try{job=null;config.remove("job");config.remove("stage");config.remove("outcome");save();showJob();stopRun("Local record cleared. Tap Send Messages to start a new approved queue.",true);}catch(Exception e){storageFailed=true;controls();}}).show();}
 private void unregister(){if(receiver!=null){try{a.unregisterReceiver(receiver);}catch(Exception ignored){}receiver=null;}}
 void pause(){active=false;stopRun("Paused because the app is no longer in the foreground. Tap Send Messages to continue.",true);}
 void resume(){active=true;if(job!=null&&"claimed".equals(config.optString("stage"))&&config.has("batch"))stopRun("Paused queue recovered. Tap Send Messages after the connection is checked.",true);controls();}
 void destroy(){destroyed=true;run.stop();handler.removeCallbacks(nextTick);if(timeout!=null)handler.removeCallbacks(timeout);unregister();io.shutdownNow();}
}
